//! ITL (Time-Location) PRS decode, validated against a real off-air frame.
//! This exact burst (captured live at 1626.1 MHz) decoded with every PRS
//! field resolving: version 2, plane 2, satellite S09, message M04 — the
//! I-channel header matched PRS_HDR[2] (a random 128-bit code) and all
//! four 96-bit message codes resolved in the 512-entry table.

use xng_mode_iridium::decode_bits;

const ORACLE: &str = "";

#[test]
fn itl_oracle_decodes_sat_plane_msg() {
    let bits: Vec<u8> = ORACLE.bytes().map(|b| b - b'0').collect();
    let f = decode_bits(&bits).expect("decodes");
    assert_eq!(f.kind, "itl");
    let d = &f.details;
    assert_eq!(d["type"], "time-location");
    assert_eq!(d["version"], 2);
    assert_eq!(d["plane"], 2);
    assert_eq!(d["sat"], "S09");
    assert_eq!(d["msg_type"], "M04");
}
